class GridTangle {
	constructor(ncols, nrows) {
		this.cols = ncols;
		this.rows = nrows;
		this.outbound = [];
		this.inbound = [];
		this.openConnectors = [];
		this.deadEnds = [];
		this.knownLoops = [];
		this.cursorx = 0;
		this.cursory = 0;
