	identifyLoops() {
		//if path loops back to itself there wont be a dead end to start path from, so we need to id a start point for each loop 
		//start point saved to knownLoops will be upper-left-most point in path
		let loopsIdentified = 0;
		for (let p = 0; p < this.rows; p++) {
			for (let i = 0; i < this.cols; i++) {
				let outd = this.outbound[p][i];
				let ind = this.inbound[p][i];
				if (outd != 'X' && ind != 'X') {
					let idx = p * this.cols + i;
					//dont want to repeat if already identified loop it is on
					if (!this.knownLoops.includes(idx)) {
						if (!this.inLoop.includes(idx)) {
