	traceToLoop(col, row) {
		//trace path from here to see if it loops
		let idxOnPath = [];
		idxOnPath.push(row * this.cols + col);
		let atx = col;
		let aty = row;
		let continuePath = true;
		let isLoop = false;
		let _wG_3 = 0; while ((continuePath) && ++_wG_3 < 20000) {
			let dirOut = this.outbound[aty][atx];
			if (dirOut == 'N') {
				aty--;
			} else if (dirOut == 'E') {
				atx++;
			} else if (dirOut == 'S') {
				aty++;
			} else if (dirOut == 'W') {
				atx--;
			} else {
				//end
				continuePath = false;
			}
			if (continuePath) {
				let idx = aty * this.cols + atx;
				if (!idxOnPath.includes(idx)) {
					idxOnPath.push(idx);
				} else {
					//is loop
					continuePath = false;
					isLoop = true;
				}
			}
		}
		if (isLoop && idxOnPath.length > 4) {
			//only want to store one point of a loop, save upper left point
			let minx = 10000;
			let miny = 10000;
			for (let i = 0; i < idxOnPath.length; i++) {
				let idx = idxOnPath[i];
				let icol = idx % this.cols;
				let irow = floor(idx / this.cols);
				if (icol < minx) {
					minx = icol;
				}
				if (irow < miny) {
					miny = irow;
				}
			}
			let idxmin = miny * this.cols + minx;
			if (!this.knownLoops.includes(idxmin)) {
				this.knownLoops.push(idxmin);
				//saving all points in a loop prevents running same search repeatedly 
				for (let i = 0; i < idxOnPath.length; i++) {
					this.inLoop.push(idxOnPath[i]);
				}
				return true;
			}
		}
		return false;
	}

