	getOpenConnector() {
		if (this.openConnectors.length < 1) {
			return -1;
		}
		return this.openConnectors[floor(random(this.openConnectors.length))];
	}

	canConnectTo(col, row, dir) {
		switch (dir) {
			case 'N':
				return this.canConnect(col, row - 1);
				break;
			case 'E':
				return this.canConnect(col + 1, row);
				break;
			case 'S':
				return this.canConnect(col, row + 1);
				break;
			case 'W':
				return this.canConnect(col - 1, row);
				break;
		}
	}

	canConnect(col, row) {
		//checks if this location is valid and connectable
		if (this.validIP(col, row)) {
			let ob = this.outbound[row][col];
			let ib = this.inbound[row][col];
			if (ob == 'X' || ib == 'X') {
				return true;
			}
		}
		return false;
	}

	makeConnection(col, row, dir, forceIt) {
		//update grid connection direction
		if (this.outbound[row][col] == 'X' || forceIt) {
			this.outbound[row][col] = dir;
			switch (dir) {
				case 'N':
					this.inbound[row - 1][col] = 'S';
					break;
				case 'E':
					this.inbound[row][col + 1] = 'W';
					break;
				case 'S':
					this.inbound[row + 1][col] = 'N';
					break;
				case 'W':
					this.inbound[row][col - 1] = 'E';
					break;
			}
			return true;
		}
		return false;
	}

	validIP(px, py) {
		//check if location in grid bounds
		if (px < 0) {
			return false;
		}
		if (py < 0) {
			return false;
		}
		if (px >= this.cols) {
			return false;
		}
		if (py >= this.rows) {
			return false;
		}
		return true;
	}

	cursorConnect() {
		//cursor travels and forges a path according to its strategy
		let nextc = this.getOpenConnector();
		if (nextc < 0) {
