				let go = this.cursorTravel(this.cursorDir);
				this.cursorContinuity++;
				if (this.cursorStrategy == "ZIGZAG") {
					//reverses direction after each segment
					if (this.cursorContinuity > this.cursorSegmentLength) {
						let templast = this.cursorDir;
						this.cursorDir = this.cursorLastDir;
						this.cursorLastDir = templast;
						this.cursorContinuity = 0;
					}
				} else if (this.cursorStrategy == "RANDOMEQUAL") {
					//each segment is same length, but direction is random
					if (this.cursorContinuity > this.cursorSegmentLength) {
						this.cursorLastDir = this.cursorDir;
						this.cursorTurnRight();
						if (random(1) > 0.5) {
							this.cursorOpposite();
						}
						this.cursorContinuity = 0;
					}
				} else if (this.cursorStrategy == "RANDOMRANDOM") {
					//direction is random and segment lengths are random
					if (this.cursorContinuity > this.cursorSegmentLength) {
						this.cursorLastDir = this.cursorDir;
						this.cursorTurnRight();
						if (random(1) > 0.5) {
							this.cursorOpposite();
						}
						this.cursorContinuity = 0;
						this.cursorSegmentLength = 2 + floor(random(5));
					}
				} else if (this.cursorStrategy == "FLATWAVE") {
					//alternates turns to make a wave
					if (this.cursorContinuity > this.cursorSegmentLength) {
						if (this.turnHistory[0] == this.turnHistory[1]) {
							//turned twice same dir, now switch
							if (this.turnHistory[0] == 1) {
								//turnRight = 1, turnLeft = 2
								this.cursorTurnRight();
								this.cursorOpposite();
								this.addTurnToHistory(2);
							} else {
								this.cursorTurnRight();
								this.addTurnToHistory(1);
							}
						} else {
							//turned only once 
							if (this.turnHistory[0] == 1) {
								//turnRight = 1, turnLeft = 2
								this.cursorTurnRight();
								this.addTurnToHistory(1);
							} else {
								this.cursorTurnRight();
								this.cursorOpposite();
								this.addTurnToHistory(2);
							}
						}
					}
				} else if (this.cursorStrategy == "BOXER") {
					//travels segment length then turns right, until it returns to origin
					if (this.cursorContinuity > this.cursorSegmentLength) {
						this.cursorTurnRight();
						this.cursorContinuity = 0;
					}
				} else if (this.cursorStrategy == "SWING"){
					//turns twice quickly, then travels
					if (this.cursorContinuity > this.cursorSegmentLength) {
						if (this.turnHistory[0] == this.turnHistory[1]) {
							//turned twice same dir, now switch
							this.cursorSegmentLength = 5 + floor(random(5));
							if (this.turnHistory[0] == 1) {
								//turnRight = 1, turnLeft = 2
								this.cursorTurnRight();
								this.cursorOpposite();
								this.addTurnToHistory(2);
							} else {
								this.cursorTurnRight();
								this.addTurnToHistory(1);
							}
						}else {
							//turned only once 
							this.cursorSegmentLength = 1;
							if (this.turnHistory[0] == 1) {
								//turnRight = 1, turnLeft = 2
								this.cursorTurnRight();
								this.addTurnToHistory(1);
							} else {
								this.cursorTurnRight();
								this.cursorOpposite();
								this.addTurnToHistory(2);
							}
						}
					}
				}
			} else {
				if (this.cursorStrategy == "BOXER") {
					let nextindex = this.indexInDir(this.cursorDir);
					if (nextindex >= 0) {
						if (nextindex == this.cursorOrigin) {
							//reconnect path to origin
							this.makeConnection(this.cursorx, this.cursory, this.cursorDir, true);
							canContinue = false;
							return true;
						}
					}
				}
				//change direction
				this.cursorLastDir = this.cursorDir;
				this.cursorContinuity = 0;
				this.cursorTurnRight();
				if (this.cursorStrategy == "STRAIGHTLEFT") {
					this.cursorOpposite();
				}
				if (this.canConnectTo(this.cursorx, this.cursory, this.cursorDir)) {
					let con = this.makeConnection(this.cursorx, this.cursory, this.cursorDir, false);
					this.openConnectors.splice(this.openConnectors.indexOf(this.cursory * this.cols + this.cursorx), 1);
					let go = this.cursorTravel(this.cursorDir);
				} else {
					this.cursorOpposite();
					if (this.canConnectTo(this.cursorx, this.cursory, this.cursorDir)) {
						let con = this.makeConnection(this.cursorx, this.cursory, this.cursorDir, false);
						this.openConnectors.splice(this.openConnectors.indexOf(this.cursory * this.cols + this.cursorx), 1);
						let go = this.cursorTravel(this.cursorDir);
